    [FunctionalFact]
    public async Task GivenForeignTrashAndTerminalRows_WhenPaging_ThenFilterBeforeTakeAndKeepInitialBoundary()
    {
        using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var foreign=await ProfileSetup.Create(fixture,owner);var trash=await Record(s);await Record(foreign);var terminal=await Record(s);var first=await Record(s);var second=await Record(s);
        await using(var db=fixture.CreateContext()){await db.Records.Where(x=>x.Id==trash.Id).ExecuteUpdateAsync(x=>x.SetProperty(r=>r.DeletedAt,DateTimeOffset.UtcNow));db.TerminalErasures.Add(new(){ResourceId=terminal.PublicId,ResourceKind="record",DeletedAt=DateTimeOffset.UtcNow});await db.SaveChangesAsync();}
        var before=await Snapshot(s);var page=await List(s,1);Assert.Null(page.Error);Assert.Equal(first.PublicId,Assert.Single(page.Data!.Items).RecordId);Assert.True(page.Data.HasMore);Assert.Equal(second.ServerSequence,page.Data.Boundary);Assert.Equal(before,await Snapshot(s));var later=await Record(s);var next=await List(s,1,first.ServerSequence,page.Data.Boundary);Assert.Null(next.Error);Assert.Equal(second.PublicId,Assert.Single(next.Data!.Items).RecordId);Assert.False(next.Data.HasMore);Assert.DoesNotContain(next.Data.Items,x=>x.RecordId==later.PublicId);Assert.Equal(first.Envelope,page.Data.Items[0].Envelope);
    }
