    [FunctionalTheory][InlineData("revoked")][InlineData("wrongRecipient")][InlineData("unknownAccess")][InlineData("zeroRevision")][InlineData("unsafeRevision")][InlineData("grantTerminal")][InlineData("collectionTrash")][InlineData("collectionTerminal")][InlineData("ownerClosing")][InlineData("ownerTerminal")][InlineData("recordTrash")][InlineData("recordTerminal")][InlineData("ancestorTrash")][InlineData("ancestorTerminal")]
    public async Task GivenHiddenSharedAuthorityOrContent_WhenListing_ThenOmitBeforePaginationWithoutNativeInspection(string kind)
    {
        using var owner=new ProtectionFixture();using var recipient=new ProtectionFixture();var foreign=await ProfileSetup.Create(fixture,owner);var s=await ProfileSetup.Create(fixture,recipient);var items=await AssociationSetup.Items(fixture,foreign);var included=await Record(foreign,items.Folder.Id);var grant=await AssociationSetup.Grant(fixture,foreign,owner,s,recipient,items.Collection);await Members(foreign,items.Collection,[included.Id],[]);
        await using(var db=fixture.CreateContext()){var g=await db.CollectionGrants.SingleAsync(x=>x.Id==grant.Id);g.RecipientKeyEnvelope="bad"u8.ToArray();if(kind=="revoked")g.State=CollectionGrantState.Revoked;if(kind=="wrongRecipient")g.RecipientAccountId=foreign.InternalId;if(kind=="unknownAccess")g.Access=(CollectionGrantAccess)99;if(kind=="zeroRevision")g.Revision=0;if(kind=="unsafeRevision")g.Revision=ProtocolBinary.MaxInteger+1;if(kind=="collectionTrash")await db.Collections.Where(x=>x.Id==items.Collection.Id).ExecuteUpdateAsync(x=>x.SetProperty(c=>c.DeletedAt,DateTimeOffset.UtcNow));if(kind=="ownerClosing")await db.Accounts.Where(x=>x.Id==foreign.InternalId).ExecuteUpdateAsync(x=>x.SetProperty(a=>a.State,AccountState.ClosurePending));if(kind=="recordTrash")await db.Records.Where(x=>x.Id==included.Id).ExecuteUpdateAsync(x=>x.SetProperty(r=>r.DeletedAt,DateTimeOffset.UtcNow));if(kind=="ancestorTrash")await db.Folders.Where(x=>x.Id==items.Folder.Id).ExecuteUpdateAsync(x=>x.SetProperty(f=>f.DeletedAt,DateTimeOffset.UtcNow));if(kind.EndsWith("Terminal",StringComparison.Ordinal))db.TerminalErasures.Add(new(){ResourceId=kind=="grantTerminal"?grant.PublicId:kind=="collectionTerminal"?items.Collection.PublicId:kind=="ownerTerminal"?foreign.AccountId:kind=="recordTerminal"?included.PublicId:items.Folder.PublicId,ResourceKind="fixture",DeletedAt=DateTimeOffset.UtcNow});await db.SaveChangesAsync();}
        var r=await List(s,1);Assert.Null(r.Error);Assert.Empty(r.Data!.Items);Assert.False(r.Data.HasMore);Assert.Equal(0,r.Data.Boundary);
    }
    [FunctionalTheory][InlineData("blob")][InlineData("signature")][InlineData("owner")][InlineData("collection")][InlineData("grant")][InlineData("recipient")][InlineData("revision")][InlineData("epoch")][InlineData("collectionEnvelope")][InlineData("ownerPins")][InlineData("recipientPins")][InlineData("missingOwnerPins")][InlineData("missingRecipientPins")][InlineData("collectionNumericString")]
    public async Task GivenCorruptRelevantNativeGrant_WhenListing_Then503WithoutPartialContent(string kind)
    {
        using var owner=new ProtectionFixture();using var recipient=new ProtectionFixture();var foreign=await ProfileSetup.Create(fixture,owner);var s=await ProfileSetup.Create(fixture,recipient);var items=await AssociationSetup.Items(fixture,foreign);var grant=await AssociationSetup.Grant(fixture,foreign,owner,s,recipient,items.Collection);await Members(foreign,items.Collection,[items.Record.Id],[]);await Record(s);
        await using(var db=fixture.CreateContext()){var g=await db.CollectionGrants.SingleAsync(x=>x.Id==grant.Id);if(kind=="blob")g.RecipientKeyEnvelope="bad"u8.ToArray();if(kind is "owner" or "collection" or "grant" or "recipient")g.RecipientKeyEnvelope=Bytes(owner.WrapGrant(kind=="owner"?Guid.NewGuid():foreign.AccountId,kind=="collection"?Guid.NewGuid():items.Collection.PublicId,kind=="grant"?Guid.NewGuid():grant.PublicId,kind=="recipient"?Guid.NewGuid():s.Actor,recipient.Material.RecipientKey));if(kind=="signature"){var wrapper=JsonSerializer.Deserialize<RecipientEnvelope>(g.RecipientKeyEnvelope,ProtectionFixture.Json)!;ProtocolBinary.TryDecode(wrapper.Signature,null,out var bytes);bytes[0]^=1;g.RecipientKeyEnvelope=Bytes(wrapper with{Signature=ProtocolBinary.Encode(bytes)});}if(kind=="revision")g.Revision=2;if(kind=="epoch")await db.Collections.Where(x=>x.Id==items.Collection.Id).ExecuteUpdateAsync(x=>x.SetProperty(c=>c.KeyEpoch,2));if(kind=="collectionNumericString")await db.Collections.Where(x=>x.Id==items.Collection.Id).ExecuteUpdateAsync(x=>x.SetProperty(c=>c.Envelope,System.Text.Encoding.UTF8.GetBytes(System.Text.Encoding.UTF8.GetString(items.Collection.Envelope).Replace("\"keyEpoch\":1","\"keyEpoch\":\"1\""))));if(kind=="collectionEnvelope")await db.Collections.Where(x=>x.Id==items.Collection.Id).ExecuteUpdateAsync(x=>x.SetProperty(c=>c.Envelope,"bad"u8.ToArray()));if(kind is "ownerPins" or "recipientPins")await db.VaultProtections.Where(x=>x.AccountId==(kind=="ownerPins"?foreign.InternalId:s.InternalId)).ExecuteUpdateAsync(x=>x.SetProperty(p=>p.Material,"bad"u8.ToArray()));if(kind is "missingOwnerPins" or "missingRecipientPins")await db.VaultProtections.Where(x=>x.AccountId==(kind=="missingOwnerPins"?foreign.InternalId:s.InternalId)).ExecuteDeleteAsync();await db.SaveChangesAsync();}
        var before=await Snapshot(s);var foreignBefore=await Snapshot(foreign);var r=await List(s,1);Assert.Equal("persistence_unavailable",r.Error);Assert.Null(r.Data);Assert.Equal(before,await Snapshot(s));Assert.Equal(foreignBefore,await Snapshot(foreign));
    }
