    public async Task GivenCurrentAccountOrSessionState_WhenListing_ThenRevalidateWithoutMutation(string kind,string? error)
    {
        using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var record=await Record(s);await using(var db=fixture.CreateContext()){var a=await db.Accounts.SingleAsync(x=>x.Id==s.InternalId);var v=await db.VaultAccessSessions.SingleAsync(x=>x.HandleVerifier==s.Verifier);if(kind=="closing")a.State=AccountState.ClosurePending;if(kind=="terminal")db.TerminalErasures.Add(new(){ResourceId=s.AccountId,ResourceKind="account",DeletedAt=DateTimeOffset.UtcNow});if(kind=="revoked")v.Revoked=true;if(kind=="expired")v.ExpiresAt=DateTimeOffset.UtcNow.AddSeconds(-1);if(kind=="future")v.IssuedAt=DateTimeOffset.UtcNow.AddMinutes(1);if(kind=="policy")v.PolicyRevision++;if(kind=="generation")v.RevocationGeneration++;if(kind=="zeroPolicy")v.PolicyRevision=0;if(kind=="zeroGeneration")v.RevocationGeneration=0;if(kind is "noExpiry" or "disabledExpiry")a.RenewalEnabled=false;if(kind is "noExpiry" or "nullExpiry")v.ExpiresAt=null;await db.SaveChangesAsync();}var before=await Snapshot(s);var r=await List(s with{Actor=kind=="missing"?Guid.NewGuid():s.Actor,Verifier=kind=="access"?new string('a',64):s.Verifier});Assert.Equal(error,r.Error);if(error is null)Assert.Equal(record.PublicId,Assert.Single(r.Data!.Items).RecordId);else Assert.Null(r.Data);Assert.Equal(before,await Snapshot(s));
    }
