    [FunctionalTheory][InlineData("grant")][InlineData("member")][InlineData("profileCollection")][InlineData("session")]
    public async Task GivenRevocationBetweenPages_WhenContinuing_ThenApplyCurrentPermissionWithoutFillingWithHiddenRows(string kind)
    {
        using var owner=new ProtectionFixture();using var recipient=new ProtectionFixture();using var scoped=new ProtectionFixture();var foreign=await ProfileSetup.Create(fixture,owner);var s=await ProfileSetup.Create(fixture,recipient);var items=await AssociationSetup.Items(fixture,foreign);var second=await Record(foreign);var grant=await AssociationSetup.Grant(fixture,foreign,owner,s,recipient,items.Collection);await Members(foreign,items.Collection,[items.Record.Id,second.Id],[]);var p=await Profile(s,recipient,scoped,collections:[items.Collection.PublicId]);var selected=s with{Verifier=await Selected(s,p.Id)};var page=(await List(selected,1)).Data!;Assert.True(page.HasMore);
        await using(var db=fixture.CreateContext()){if(kind=="grant")await db.CollectionGrants.Where(x=>x.Id==grant.Id).ExecuteUpdateAsync(x=>x.SetProperty(g=>g.State,CollectionGrantState.Revoked));if(kind=="member")await db.CollectionRecords.Where(x=>x.CollectionId==items.Collection.Id && x.RecordId==second.Id).ExecuteDeleteAsync();if(kind=="profileCollection")await db.ProfileCollections.Where(x=>x.ProfileId==p.Id).ExecuteDeleteAsync();if(kind=="session")await db.VaultAccessSessions.Where(x=>x.HandleVerifier==selected.Verifier).ExecuteUpdateAsync(x=>x.SetProperty(v=>v.Revoked,true));}
        var r=await List(selected,1,page.Items[0].ServerSequence,page.Boundary);if(kind=="session"){Assert.Equal("vault_access_denied",r.Error);Assert.Null(r.Data);}else{Assert.Null(r.Error);Assert.Empty(r.Data!.Items);Assert.False(r.Data.HasMore);Assert.Equal(page.Boundary,r.Data.Boundary);}
    }
