    [FunctionalFact]
    public async Task GivenUnavailableMembershipTable_WhenListing_Then503AndRestoreDependency()
    {using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var before=await Snapshot(s);await using var db=fixture.CreateContext();await db.Database.ExecuteSqlRawAsync("ALTER TABLE cerberus.collection_record RENAME TO fixture_unavailable_collection_record");try{var r=await List(s);Assert.Equal("persistence_unavailable",r.Error);Assert.Null(r.Data);}finally{await db.Database.ExecuteSqlRawAsync("ALTER TABLE cerberus.fixture_unavailable_collection_record RENAME TO collection_record");}Assert.Equal(before,await Snapshot(s));}
    [FunctionalFact]
    public async Task GivenCancelledCaller_WhenListing_ThenPropagateWithoutChangingState()
    {using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var before=await Snapshot(s);using var ct=new CancellationTokenSource();ct.Cancel();await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>Store().ListAsync(new(s.Actor,s.Verifier,10,0,null),ct.Token));Assert.Equal(before,await Snapshot(s));}

    [FunctionalTheory][InlineData(false,false)][InlineData(false,true)][InlineData(true,false)][InlineData(true,true)]
    public async Task GivenHiddenAncestorAndCycle_WhenListing_ThenOmitBeforeInspectingCorruption(bool selected,bool terminal)
    {using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var root=await Folder(s);var child=await Folder(s,root.Id);var hidden=await Record(s,child.Id);var visible=await Record(s);var p=await Profile(s,owner,scoped,[hidden.PublicId,visible.PublicId],[root.PublicId]);await using(var db=fixture.CreateContext()){await db.Folders.Where(x=>x.Id==root.Id).ExecuteUpdateAsync(x=>x.SetProperty(f=>f.ParentFolderId,child.Id).SetProperty(f=>f.DeletedAt,terminal?(DateTimeOffset?)null:DateTimeOffset.UtcNow));if(terminal){db.TerminalErasures.Add(new(){ResourceId=root.PublicId,ResourceKind="folder",DeletedAt=DateTimeOffset.UtcNow});await db.SaveChangesAsync();}}var r=await List(selected?s with{Verifier=await Selected(s,p.Id)}:s);Assert.Null(r.Error);Assert.Equal(visible.PublicId,Assert.Single(r.Data!.Items).RecordId);}

    [FunctionalTheory][InlineData(false,true,false)][InlineData(true,true,false)][InlineData(true,false,false)][InlineData(true,true,true)]
    public async Task GivenUnrelatedDeepFolderInventory_WhenListingOnePermittedRecord_ThenDoNotAdmitOrTraverseUnrelatedRows(bool selected,bool foreign,bool shared)
    {
        using var owner=new ProtectionFixture();using var scoped=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);
        var unrelated=foreign?await ProfileSetup.Create(fixture,owner):s;var visible=await Record(shared?unrelated:s);Guid[] collections=[];
        if(shared){var resources=await AssociationSetup.Items(fixture,unrelated);await AssociationSetup.Grant(fixture,unrelated,owner,s,owner,resources.Collection);await Members(unrelated,resources.Collection,[visible.Id],[]);collections=[resources.Collection.PublicId];}
        var p=await Profile(s,owner,scoped,shared?[]:[visible.PublicId],collections:collections);
        long? parent=null;for(var depth=0;depth<100;depth++){var folder=await Folder(unrelated,parent);await Record(unrelated,folder.Id);parent=folder.Id;}
        var capture=new CapturePlan();var store=new RecordListStore(new ProfileSetup.Factory(fixture,capture));
        var result=await store.ListAsync(new(s.Actor,selected?await Selected(s,p.Id):s.Verifier,1,0,null),default);
        Assert.Null(result.Error);Assert.Equal(visible.PublicId,Assert.Single(result.Data!.Items).RecordId);Assert.False(result.Data.HasMore);Assert.Equal(1,capture.Readers);
        await using var db=fixture.CreateContext();await db.Database.OpenConnectionAsync();await using var command=db.Database.GetDbConnection().CreateCommand();
        command.CommandText="EXPLAIN (ANALYZE, FORMAT JSON) "+capture.Sql;foreach(var parameter in capture.Parameters)command.Parameters.Add(parameter.Clone());
        using var plan=JsonDocument.Parse((string)(await command.ExecuteScalarAsync())!);output.WriteLine(plan.RootElement.GetRawText());
        static IEnumerable<JsonElement> Nodes(JsonElement node){yield return node;if(node.TryGetProperty("Plans",out var children))foreach(var child in children.EnumerateArray())foreach(var descendant in Nodes(child))yield return descendant;}
        var nodes=Nodes(plan.RootElement[0].GetProperty("Plan")).ToArray();
        var candidates=Assert.Single(nodes,x=>x.TryGetProperty("Subplan Name",out var name)&&name.GetString()=="CTE candidates");
        var ancestry=Assert.Single(nodes,x=>x.TryGetProperty("Subplan Name",out var name)&&name.GetString()=="CTE ancestry");
        Assert.Equal(1d,candidates.GetProperty("Actual Rows").GetDouble());Assert.Equal(0d,ancestry.GetProperty("Actual Rows").GetDouble());
    }
    private sealed class CapturePlan:DbCommandInterceptor
    {
        public int Readers{get;private set;}public string Sql{get;private set;}="";public NpgsqlParameter[] Parameters{get;private set;}=[];
        public override ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(DbCommand command,CommandEventData data,InterceptionResult<DbDataReader> result,CancellationToken ct=default)
        {Readers++;Sql=command.CommandText;Parameters=command.Parameters.Cast<NpgsqlParameter>().Select(x=>x.Clone()).ToArray();return ValueTask.FromResult(result);}
    }

    private RecordListStore Store()=>new(fixture);
    private Task<VaultResult<RecordListPage>> List(ProfileSetup.State s,int size=100,long after=0,long? boundary=null)=>Store().ListAsync(new(s.Actor,s.Verifier,size,after,boundary),default);
    private async Task<VaultRecord> Record(ProfileSetup.State s,long? folder=null){var row=new VaultRecord{PublicId=Guid.NewGuid(),AccountId=s.InternalId,FolderId=folder,Envelope=Bytes(ProfileSetup.Envelope()),EditedAt=DateTimeOffset.UnixEpoch};await using var db=fixture.CreateContext();db.Records.Add(row);await db.SaveChangesAsync();return row;}
    private async Task<VaultFolder> Folder(ProfileSetup.State s,long? parent=null){var row=new VaultFolder{PublicId=Guid.NewGuid(),AccountId=s.InternalId,ParentFolderId=parent,Envelope=Bytes(ProfileSetup.Envelope()),EditedAt=DateTimeOffset.UnixEpoch};await using var db=fixture.CreateContext();db.Folders.Add(row);await db.SaveChangesAsync();return row;}
    private async Task<Profile> Profile(ProfileSetup.State s,ProtectionFixture owner,ProtectionFixture scoped,Guid[]? records=null,Guid[]? folders=null,Guid[]? collections=null){var input=ProfileSetup.Input(s,owner,scoped) with{RecordIds=records??[],FolderIds=folders??[],CollectionIds=collections??[]};Assert.Null((await new ProfileCreateStore(fixture).CreateAsync(new(s.Actor,s.Verifier,input),default)).Error);await using var db=fixture.CreateContext();return await db.Profiles.AsNoTracking().SingleAsync(x=>x.PublicId==input.ProfileId);}
    private async Task Members(ProfileSetup.State s,VaultCollection collection,long[] records,long[] folders){await using var db=fixture.CreateContext();db.CollectionRecords.AddRange(records.Select(x=>new CollectionRecord{AccountId=s.InternalId,CollectionId=collection.Id,RecordId=x}));db.CollectionFolders.AddRange(folders.Select(x=>new CollectionFolder{AccountId=s.InternalId,CollectionId=collection.Id,FolderId=x}));await db.SaveChangesAsync();}
    private async Task<string> Selected(ProfileSetup.State s,long profile){var verifier=Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(32));await using var db=fixture.CreateContext();db.VaultAccessSessions.Add(new(){AccountId=s.InternalId,ProfileId=profile,HandleVerifier=verifier,IssuedAt=DateTimeOffset.UtcNow.AddMinutes(-1),ExpiresAt=DateTimeOffset.UtcNow.AddHours(1),PolicyRevision=1,RevocationGeneration=1});await db.SaveChangesAsync();return verifier;}
    private static byte[] Bytes<T>(T value)=>JsonSerializer.SerializeToUtf8Bytes(value,ProtectionFixture.Json);
    private async Task<string> Snapshot(ProfileSetup.State s){await using var db=fixture.CreateContext();return JsonSerializer.Serialize(new{Account=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==s.InternalId),Protection=await db.VaultProtections.AsNoTracking().SingleOrDefaultAsync(x=>x.AccountId==s.InternalId),Sessions=await db.VaultAccessSessions.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Records=await db.Records.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Folders=await db.Folders.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Collections=await db.Collections.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),Profiles=await db.Profiles.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.Id).ToArrayAsync(),ProfileRecords=await db.ProfileRecords.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.ProfileId).ThenBy(x=>x.RecordId).ToArrayAsync(),ProfileFolders=await db.ProfileFolders.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.ProfileId).ThenBy(x=>x.FolderId).ToArrayAsync(),ProfileCollections=await db.ProfileCollections.AsNoTracking().Where(x=>db.Profiles.Any(p=>p.Id==x.ProfileId && p.AccountId==s.InternalId)).OrderBy(x=>x.ProfileId).ThenBy(x=>x.CollectionId).ToArrayAsync(),CollectionRecords=await db.CollectionRecords.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.CollectionId).ThenBy(x=>x.RecordId).ToArrayAsync(),CollectionFolders=await db.CollectionFolders.AsNoTracking().Where(x=>x.AccountId==s.InternalId).OrderBy(x=>x.CollectionId).ThenBy(x=>x.FolderId).ToArrayAsync(),Grants=await db.CollectionGrants.AsNoTracking().Where(x=>x.RecipientAccountId==s.InternalId || db.Collections.Any(c=>c.Id==x.CollectionId && c.AccountId==s.InternalId)).OrderBy(x=>x.Id).ToArrayAsync()});}
    private sealed class RevokeAfterRead(PostgresFixture fixture,long grant):DbCommandInterceptor
    {public int Readers{get;private set;}public override async ValueTask<DbDataReader> ReaderExecutedAsync(DbCommand c,CommandExecutedEventData e,DbDataReader reader,CancellationToken ct=default){Readers++;if(Readers==1){await using var db=fixture.CreateContext();await db.CollectionGrants.Where(x=>x.Id==grant).ExecuteUpdateAsync(x=>x.SetProperty(g=>g.State,CollectionGrantState.Revoked),ct);}return reader;}}
    private sealed class ExpireBeforeRead(DateTimeOffset deadline):DbCommandInterceptor
    {public override async ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(DbCommand c,CommandEventData e,InterceptionResult<DbDataReader> result,CancellationToken ct=default){var wait=deadline-DateTimeOffset.UtcNow;if(wait>TimeSpan.Zero)await Task.Delay(wait+TimeSpan.FromMilliseconds(100),ct);return result;}}
